<template>
  <view v-if="desktop && chatEnabled" class="desktop-chat-dock">
    <view v-if="everOpened" v-show="opened" class="desktop-chat-panel" role="dialog" aria-label="湖财对话窗口" :aria-hidden="!opened">
      <view class="desktop-chat-heading"><view><text>湖财对话</text><text>边浏览，边与校友畅聊</text></view><button aria-label="收起对话窗口" title="收起对话窗口" @tap="close">—</button></view>
      <view class="desktop-chat-body"><view class="desktop-chat-list"><ConversationList ref="list" embedded :active="working" @conversation="select" @navigate="close" @unread="unread=$event"/></view><view class="desktop-chat-thread"><ChatThread v-if="selectedId" :key="selectedId+'-'+sessionVersion" ref="thread" embedded :conversation-id="selectedId" :active="working" @back="selectedId=''"/><view v-else class="desktop-chat-placeholder"><text class="desktop-chat-symbol">聊</text><text>选择一个对话</text><text>可以与校友一对一聊天，也可以创建群聊。</text><text>支持文字、图片、文件和后台上架的表情包。</text></view></view></view>
    </view>
    <button ref="trigger" class="desktop-chat-trigger" :class="{'is-open':opened}" :aria-expanded="opened" aria-label="打开湖财对话" title="湖财对话" @tap="toggle"><view class="desktop-chat-icon"><text>•••</text></view><text>{{ opened?'收起对话':'对话' }}</text><text v-if="unread&&!opened" class="desktop-chat-unread">{{ unread>99?'99+':unread }}</text></button>
  </view>
</template>
<script>
import ConversationList from './ConversationList.vue'
import ChatThread from './ChatThread.vue'
import {chatApi} from '../services/chat'
import {getMyInbox} from '../services/business'
import {getAccessToken} from '../utils/store'
import {enforceInitialPasswordChange} from '../utils/passwordChange'
import {DESKTOP_CHAT_QUERY} from '../utils/desktopChat'
import {isModuleEnabled} from '../services/modules'
export default{
  components:{ConversationList,ChatThread},
  data:()=>({desktop:false,opened:false,everOpened:false,selectedId:'',unread:0,sessionToken:'',sessionVersion:0,background:false,timer:null,query:null,unreadGeneration:0}),
  computed:{chatEnabled(){return isModuleEnabled('chat')},working(){return this.chatEnabled&&this.desktop&&this.opened&&!this.background}},
  watch:{chatEnabled(enabled){if(!enabled){this.opened=false;this.everOpened=false;this.selectedId='';this.unread=0;this.unreadGeneration++}}},
  mounted(){this.query=window.matchMedia(DESKTOP_CHAT_QUERY);this.desktop=this.query.matches;this.sessionToken=getAccessToken();this.query.addEventListener('change',this.resize);window.addEventListener('hufe:open-desktop-chat',this.requestOpen);window.addEventListener('keydown',this.keydown);document.addEventListener('visibilitychange',this.visibility);uni.$on('hufe:auth-changed',this.authChanged);window.__hufeDesktopChatReady=true;this.timer=setInterval(this.checkUnread,12000);this.checkUnread()},
  beforeUnmount(){this.unreadGeneration++;clearInterval(this.timer);this.query?.removeEventListener('change',this.resize);window.removeEventListener('hufe:open-desktop-chat',this.requestOpen);window.removeEventListener('keydown',this.keydown);document.removeEventListener('visibilitychange',this.visibility);uni.$off('hufe:auth-changed',this.authChanged);window.__hufeDesktopChatReady=false},
  methods:{
    resize(event){this.desktop=event.matches;if(!this.desktop)this.close();else this.checkUnread()},
    visibility(){this.background=document.hidden;if(!this.background)this.checkUnread()},
    authChanged(){const token=getAccessToken();if(token===this.sessionToken)return;this.sessionToken=token;this.unreadGeneration++;this.sessionVersion++;this.selectedId='';this.unread=0;this.opened=false;this.everOpened=false;this.checkUnread()},
    async checkUnread(){if(!this.chatEnabled)return;const token=getAccessToken();if(token!==this.sessionToken){this.authChanged();return}if(!this.desktop||this.background||!token){if(!token)this.unread=0;return}if(this.opened)return;const generation=++this.unreadGeneration;const [chat,inbox]=await Promise.allSettled([chatApi('/conversations',{token}),getMyInbox({page:1,pageSize:1},{token})]);if(!this.chatEnabled||generation!==this.unreadGeneration||token!==getAccessToken())return;const chatCount=chat.status==='fulfilled'?chat.value.items.reduce((sum,item)=>sum+Number(item.unread||0),0):0;const inboxCount=inbox.status==='fulfilled'?Math.max(0,Number(inbox.value.unread)||0):0;this.unread=chatCount+inboxCount},
    requestOpen(event){if(!this.chatEnabled||!this.desktop||enforceInitialPasswordChange())return;this.authChanged();this.everOpened=true;this.opened=true;const id=String(event.detail?.conversationId||'');if(id)this.select(id);this.$nextTick(()=>{if(this.working)this.$refs.list?.load()})},
    select(id){if(!this.chatEnabled||!this.desktop||!/^[A-Za-z0-9_-]{1,120}$/.test(String(id)))return;this.selectedId=id;this.$nextTick(()=>{if(this.working)this.$refs.list?.load()})},
    toggle(){if(this.opened)this.close();else this.requestOpen({detail:{}})},
    close(){this.opened=false;this.unreadGeneration++;this.checkUnread()},
    keydown(event){if(event.key==='Escape'&&this.opened){this.close();this.$nextTick(()=>{const element=this.$refs.trigger?.$el||this.$refs.trigger;element?.focus?.()})}}
  }
}
</script>
<style scoped>
.desktop-chat-dock{position:fixed;right:28px;bottom:28px;z-index:1200;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;color:#243650}.desktop-chat-trigger{position:relative;display:flex;align-items:center;gap:11px;border:0!important;box-sizing:border-box;margin:0;padding:0 22px;height:58px;line-height:58px;border-radius:19px;background:linear-gradient(130deg,#063880,#235ca6);color:#fff;font-size:17px;font-weight:650;box-shadow:0 10px 28px #0b327749;cursor:pointer}.desktop-chat-trigger:after{border:0}.desktop-chat-trigger.is-open{background:#274b77}.desktop-chat-icon{width:26px;height:23px;display:flex;align-items:center;justify-content:center;border:2px solid #fff;border-radius:8px;position:relative;line-height:12px;font-size:14px;letter-spacing:1px}.desktop-chat-icon:after{content:'';position:absolute;bottom:-5px;left:4px;width:5px;height:7px;background:#13488e;border-left:2px solid #fff;transform:skewY(-35deg)}.desktop-chat-unread{position:absolute;top:-7px;right:-7px;min-width:24px;height:24px;line-height:24px;padding:0 7px;border-radius:14px;background:#d74646;color:#fff;border:2px solid white;font-size:12px}.desktop-chat-panel{position:absolute;right:0;bottom:76px;width:min(900px,calc(100vw - 56px));height:min(700px,calc(100dvh - 196px));min-height:0;border:1px solid #d7e1ec;border-radius:20px;background:#fff;overflow:hidden;box-shadow:0 18px 70px #17345c3b;display:flex;flex-direction:column}.desktop-chat-heading{height:62px;padding:0 20px;border-bottom:1px solid #dce6ef;background:linear-gradient(100deg,#f2f6fc,#fff);display:flex;align-items:center;justify-content:space-between;flex-shrink:0}.desktop-chat-heading>view{display:flex;align-items:center;gap:16px}.desktop-chat-heading>view>text:first-child{font-size:18px;font-weight:700;color:#214978}.desktop-chat-heading>view>text+text{font-size:12px;color:#8091a6}.desktop-chat-heading button{margin:0;border:0;background:#e6edf6;color:#38597f;width:34px;height:32px;line-height:30px;border-radius:9px;font-size:22px;padding:0}.desktop-chat-body{display:flex;flex:1;min-height:0;position:relative}.desktop-chat-list{width:300px;flex-shrink:0;border-right:1px solid #dfe7f1;min-height:0;overflow:hidden}.desktop-chat-thread{flex:1;min-width:0;min-height:0;overflow:hidden}.desktop-chat-placeholder{height:100%;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:14px;background:linear-gradient(145deg,#f5f8fd,#fff);text-align:center;padding:28px}.desktop-chat-symbol{display:flex;align-items:center;justify-content:center;width:76px;height:76px;background:#e8effa;border-radius:24px;color:#3c669b;font-size:28px;margin-bottom:10px}.desktop-chat-placeholder>text:nth-child(2){font-size:21px;font-weight:650;color:#44658f}.desktop-chat-placeholder>text:nth-child(n+3){font-size:13px;line-height:1.6;color:#8898ab}@media(max-height:650px){.desktop-chat-panel{height:calc(100dvh - 176px);min-height:0;bottom:67px}.desktop-chat-dock{bottom:16px}.desktop-chat-trigger{height:48px;line-height:48px}.desktop-chat-heading{height:48px}}@media(max-width:1023px),(pointer:coarse){.desktop-chat-dock{display:none!important}}
</style>
